/** Credential requirement declared server-side per route. */
export type AuthMode = "none" | "optional" | "required";

/** Success-body contract declared server-side per route. */
export type ResponseMode = "json" | "void" | "raw";

/**
 * One route as data. Everything the transport does is derived from these
 * fields: `cache: "no-store"` follows from `auth !== "none"`, redirect
 * following needs `auth === "none"` plus `allowRedirects`, and the replay
 * hook is consulted only for `auth === "required"` under the bearer scheme.
 * `path` holes (`{name}`) are interpolated from call args, encodeURIComponent'd.
 */
export interface OperationSpec {
  readonly method: string;
  readonly path: string;
  /** Path-parameter names, in path order. */
  readonly params?: readonly string[];
  readonly auth: AuthMode;
  /** Present when the route takes a JSON request body. */
  readonly body?: "json";
  readonly response: ResponseMode;
  readonly allowRedirects?: boolean;
  /** Present when the route is a WebSocket endpoint. */
  readonly ws?: boolean;
}

/** Per-call arguments; the route method's signature types each field. */
export interface CallArgs {
  params?: Record<string, string>;
  query?: Record<string, unknown>;
  body?: unknown;
}

/** Credential lifecycle declared server-side via `auth_scheme!`, as data.
 *  Emitted for the application's own glue — the transport does not read
 *  it. The generated file ships a typed renewal helper alongside, so the
 *  field names below are checked against the real response type. */
export type AuthStrategy =
  | { readonly kind: "static_bearer" }
  | {
      readonly kind: "exchange";
      /** OPERATIONS key of the renewal route. */
      readonly refresh: string;
      /** Response field carrying the token. */
      readonly field?: string;
      /** Whether proactive expiry may be derived from the JWT `exp` claim. */
      readonly expiryFromJwt?: boolean;
      readonly skewMs: number;
    }
  | {
      readonly kind: "oauth2";
      /** OPERATIONS key of the renewal route. */
      readonly refresh: string;
      readonly fields?: {
        readonly access: string;
        readonly refresh?: string;
        readonly expiresIn?: string;
      };
      readonly skewMs: number;
    };

/** Flow facts beyond the strategy: lifecycle route aliases and pinned
 *  constants, for app glue that wants them programmatically. */
export interface FlowManifest {
  readonly bootstrap: readonly string[];
  readonly constants: Readonly<Record<string, string>>;
}

