/** Resolved transport configuration — the generated factory bakes the
 *  server-declared defaults (credentials mode, CSRF header) before
 *  calling `createTransport`. */
export interface TransportOptions {
  baseUrl: string;
  credentials: RequestCredentials;
  fetch?: typeof fetch;
  requestInit?: Omit<RequestInit, "headers"> & { headers?: Record<string, string> };
  allowInsecureHttp?: boolean;
  onError?: (error: ApiError) => void;
  /** Best-effort observability; receives the operation descriptor. */
  onRequest?: (op: Readonly<OperationSpec>, url: string) => void;
  onResponse?: (op: Readonly<OperationSpec>, response: Response) => void;
  /** The bearer source. Consulted on every credentialed call; the one
   *  place the application names where the credential lives. */
  getToken?: () => Promise<string | null> | string | null;
  /**
   * Renewal policy. Invoked after a 401 on a `required` route under the
   * bearer scheme; return the credential to replay with, or `null` when the
   * session cannot be renewed. Throwing is treated as `null`.
   *
   * The replay credential is this function's *return value* — the transport
   * never re-reads `getToken` to decide who the caller is now, so it cannot
   * re-send a request under a session the application has since replaced.
   * Call it yourself (not only through this hook) to renew ahead of expiry.
   */
  onUnauthorized?: () => Promise<string | null>;
  /** Anti-CSRF proof source (cookie scheme, when configured). Sync and
   *  async forms both accepted — the executor awaits either. */
  csrfToken?: () => Promise<string | undefined | null> | string | undefined | null;
  /** Header name for the CSRF proof (cookie scheme, when configured). */
  csrfHeader?: string;
}

/** The executor handed to the generated routes factory. */
export interface Transport {
  execute<T = unknown>(op: Readonly<OperationSpec>, args?: CallArgs): Promise<T>;
  /** URL builder for redirect-declared routes. */
  urlFor(op: Readonly<OperationSpec>, args?: CallArgs): string;
  /** WebSocket connect; runs the ticket handshake when one is wired.
    *  Event types are part of the route contract — every WS method gets
    *  the typed JSON-codec wrapper. */
  connect<TSend = unknown, TReceive = unknown>(
    op: Readonly<OperationSpec>,
    args?: CallArgs,
  ): Promise<TypedWebSocket<TSend, TReceive>>;
}

// ---------------------------------------------------------------------------
// Transport guard
// ---------------------------------------------------------------------------

function assertSecureTransport(
  url: string,
  opts: { allowInsecureHttp: boolean; auth: boolean; credentials: string },
): void {
  const { allowInsecureHttp, auth, credentials } = opts;
  // Transport guard: credentials must only ride https. Loopback hosts are
  // inherently local and always allowed over http; anything else requires
  // the explicit allowInsecureHttp development opt-in. Fails closed on
  // unparseable URLs and non-http(s) protocols.
  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    throw new Error(
      `Client produced an unparseable URL (${JSON.stringify(url)}); refusing to send credentials.`,
    );
  }
  if (parsed.protocol === "https:" || parsed.protocol === "wss:") return;
  const h = parsed.hostname;
  const isLoopback =
    h === "localhost" ||
    h.endsWith(".localhost") ||
    h === "127.0.0.1" ||
    h === "::1" ||
    h === "[::1]";
  const isInsecureScheme = parsed.protocol === "http:" || parsed.protocol === "ws:";
  const insecureAllowed = isInsecureScheme && (isLoopback || allowInsecureHttp);
  if (!insecureAllowed) {
    throw new Error(
      parsed.protocol === "http:"
        ? `Refusing to send credentials over http:// to non-loopback host "${h}". Use https:// in production; set allowInsecureHttp on the client options for LAN/device development.`
        : `Unsupported protocol ${parsed.protocol} for credential-bearing requests.`,
    );
  }
  // allowInsecureHttp permits the HTTP connection itself, but never for
  // credential-bearing requests (auth or cookies) to non-loopback hosts.
  // Cookies count: even with auth:false, `credentials: "include"` (or
  // `"same-origin"` to a same-origin http target) still sends cookies.
  if (isInsecureScheme && !isLoopback && (auth || credentials !== "omit")) {
    throw new Error(
      `Refusing to send credentials over http:// to non-loopback host "${h}". Set allowInsecureHttp for the connection, but credentialed requests (auth: true or credentials !== "omit") still require https:// or a loopback host.`,
    );
  }
}

// ---------------------------------------------------------------------------
// Application-facing primitives
// ---------------------------------------------------------------------------

/** Expiry (epoch ms) from an unverified JWT `exp` claim — scheduling only;
    verification is server-side. Degrades to null where `atob` is missing
    (some JS runtimes). Pair with your own renewal schedule: this reads a
    claim, it does not renew anything. */
export function jwtExpiry(token: string): number | null {
  try {
    if (typeof atob !== "function") return null;
    const part = token.split(".")[1];
    if (!part) return null;
    const b64 = part.replace(/-/g, "+").replace(/_/g, "/");
    const json = decodeURIComponent(
      atob(b64)
        .split("")
        .map((c) => "%" + ("00" + c.charCodeAt(0).toString(16)).slice(-2))
        .join(""),
    );
    const exp = JSON.parse(json)?.exp;
    return typeof exp === "number" ? exp * 1000 : null;
  } catch {
    return null;
  }
}

/** Coalesce concurrent invocations of `fn` into one in-flight promise:
 *  joiners share the initiator's result, and the next caller after it
 *  settles starts a fresh call. Renewal code needs this — without it, a
 *  burst of parallel 401s mints N tokens, and under a rotating refresh
 *  token the earlier ones are already invalidated by the time they land.
 *
 *  Single-flight is per closure, so scope it to one credential source;
 *  cross-tab coordination is the application's to add on top. */
export function singleFlight<T>(fn: () => Promise<T>): () => Promise<T> {
  let inFlight: Promise<T> | null = null;
  return () => {
    if (inFlight === null) {
      inFlight = fn().finally(() => {
        inFlight = null;
      });
    }
    return inFlight;
  };
}

// ---------------------------------------------------------------------------
// Transport
// ---------------------------------------------------------------------------

export type TransportScheme = "bearer" | "cookie" | "none";

/** Render a key for an error message without letting quotes or newlines
 *  out of it. */
function escapeKeyForMessage(key: string): string {
  return key.replace(/[\\"␀-]/g, "�");
}

/** Transport-level wiring declared server-side. The WS ticket mint is
 *  transport wiring, not credential strategy: it applies with or without
 *  a declared flow (config-only clients get a synthetic operation). */
export interface TransportPolicy {
  readonly scheme: TransportScheme;
  /** OPERATIONS key of the WS ticket mint, when one is wired. */
  readonly wsTicket?: string | null;
}

/** Replay bound for the 401 path. A request that failed authentication may
 *  be re-sent, never looped: three sends is the most the transport will
 *  make for one call. Not an option — the bound belongs to the transport's
 *  replay contract, not to the application's configuration. */
const MAX_REPLAYS = 2;

export function createTransport(
  options: TransportOptions,
  policy: TransportPolicy,
  operations: Record<string, Readonly<OperationSpec>>,
): Transport {
  const { baseUrl, credentials } = options;
  const scheme = policy.scheme;
  // Bind fetch to its original receiver: calling an unbound
  // globalThis.fetch reference throws "Illegal invocation" in several
  // browser engines.
  const boundFetch =
    options.fetch !== undefined ? options.fetch : globalThis.fetch.bind(globalThis);

  // Best-effort observer dispatch: the `void` callback types accept async
  // functions, whose rejections a surrounding try/catch cannot see. Swallow
  // both sync throws and async rejections without delaying the request —
  // observers observe, they never break the call.
  function notifyObserver(fn: () => unknown): void {
    try {
      const result = fn();
      if (result instanceof Promise) result.catch(() => {});
    } catch {
      /* telemetry is not the call */
    }
  }

  // Release a discarded response's connection for reuse. Node's fetch
  // (undici) only returns pooled sockets once the body is consumed or
  // cancelled; a replayed 401 or an unread `void` body would otherwise pin
  // its connection until garbage collection.
  async function releaseBody(response: Response): Promise<void> {
    try {
      await response.body?.cancel();
    } catch {
      /* best-effort */
    }
  }

  function interpolate(op: Readonly<OperationSpec>, args: CallArgs | undefined): string {
    if (!op.path.includes("{")) return op.path;
    const values = args?.params ?? {};
    return op.path.replace(/\{([^}]+)\}/g, (_hole, name: string) => {
      const v = values[name];
      if (v === undefined) {
        throw new Error(
          `Missing path parameter "${name}" for ${op.method} ${op.path} — the typed client always supplies it.`,
        );
      }
      return encodeURIComponent(String(v));
    });
  }

  /** Arrays expand to repeated keys (?tag=a&tag=b), the conventional
   *  encoding for list-valued parameters — one shape for HTTP calls,
   *  URL builders, and WebSocket upgrades alike. */
  function appendQuery(params: URLSearchParams, query: Record<string, unknown>): void {
    for (const [key, value] of Object.entries(query)) {
      for (const v of Array.isArray(value) ? value : [value]) {
        if (v !== undefined && v !== null) {
          params.append(key, String(v));
        }
      }
    }
  }

  function buildUrl(op: Readonly<OperationSpec>, args: CallArgs | undefined): string {
    let url = `${baseUrl}${interpolate(op, args)}`;
    if (args?.query) {
      const params = new URLSearchParams();
      appendQuery(params, args.query);
      const qs = params.toString();
      if (qs) url += `?${qs}`;
    }
    return url;
  }

  interface InternalCall {
    /** Replays already consumed on this call. */
    replays?: number;
    /** Bearer for the replay — the renewal hook's return value, never a
     *  re-read of the application's credential source. */
    tokenOverride?: string;
  }

  /** Resolve an OPERATIONS key, failing loudly on an unknown one. Every
   *  key the transport resolves comes from generated code, so a miss means
   *  the client and its OPERATIONS table disagree — say so, rather than
   *  dereferencing undefined somewhere further down. */
  function requireOp(key: string): Readonly<OperationSpec> {
    const op = operations[key];
    if (op === undefined) {
      throw new Error(
        `Unknown operation "${escapeKeyForMessage(key)}" — this client's OPERATIONS table has no such key.`,
      );
    }
    return op;
  }

  async function executeInternal<T = unknown>(
    opKey: string | Readonly<OperationSpec>,
    args?: CallArgs,
    internal?: InternalCall,
  ): Promise<T> {
    const op = typeof opKey === "string" ? requireOp(opKey) : opKey;
    const authMode = op.auth;
    const permissive = authMode === "optional";
    const method = op.method;

    const url = buildUrl(op, args);

    const headers: Record<string, string> = {
      ...(args?.body !== undefined ? { "Content-Type": "application/json" } : {}),
      ...(options.requestInit?.headers ?? {}),
    };

    // Credentials are only sent over https, to loopback hosts over http,
    // or when the client was explicitly configured with allowInsecureHttp.
    // allowInsecureHttp permits the HTTP connection itself, but never for
    // credential-bearing requests (auth or cookies) to non-loopback hosts.
    assertSecureTransport(url, {
      allowInsecureHttp: options.allowInsecureHttp === true,
      auth: authMode !== "none",
      credentials,
    });

    // Best-effort observers: a throwing (or rejecting) callback never takes
    // the request down with it.
    notifyObserver(() => options.onRequest?.(op, url));

    // Bearer actually sent with this call, so the replay path can refuse to
    // re-send the credential the server just rejected.
    let sentBearer: string | null = null;
    if (scheme === "bearer" && authMode !== "none") {
      const replayed = internal?.tokenOverride;
      const tokenSource =
        replayed != null ? async (): Promise<string | null> => replayed : options.getToken;
      if (permissive) {
        if (tokenSource) {
          const token = await tokenSource();
          sentBearer = token;
          if (token) headers.Authorization = `Bearer ${token}`;
        }
      } else {
        if (!tokenSource) {
          throw new Error(
            `Route declared [auth] but no token source was configured (getToken) (${method} ${op.path})`,
          );
        }
        const token = await tokenSource();
        sentBearer = token;
        if (!token) {
          throw new Error(
            `The configured token source returned no token for an [auth] route (${method} ${op.path})`,
          );
        }
        headers.Authorization = `Bearer ${token}`;
      }
    } else if (scheme === "cookie" && authMode === "required") {
      // An [auth] route rides the browser's session cookies; refuse
      // consumer configurations that would strip them instead of sending
      // the request unauthenticated.
      if (credentials === "omit") {
        throw new Error(
          `Route declared [auth] but options.credentials is "omit"; refusing to send an unauthenticated request (${method} ${op.path})`,
        );
      }
    }

    // Anti-CSRF proof on mutating requests when configured (cookie
    // scheme). GET/HEAD/OPTIONS are safe methods and never carry it.
    if (
      scheme === "cookie" &&
      options.csrfHeader != null &&
      !["GET", "HEAD", "OPTIONS"].includes(method.toUpperCase())
    ) {
      const csrfToken = await options.csrfToken?.();
      if (csrfToken) headers[options.csrfHeader] = csrfToken;
    }

    // Only credentialless calls to routes declaring `[allow_redirects]`
    // follow redirects; anything carrying auth or cookies refuses, since
    // the guard sees only the initial URL and a 3xx could bounce to http://.
    const canFollowRedirects =
      authMode === "none" && credentials === "omit" && op.allowRedirects === true;
    const response = await boundFetch(url, {
      ...options.requestInit,
      ...(authMode !== "none" ? { cache: "no-store" as const } : {}),
      redirect: canFollowRedirects ? "follow" : "error",
      method,
      credentials,
      headers,
      body: args?.body !== undefined ? JSON.stringify(args.body) : undefined,
    });

    if (!response.ok) {
      // Replay hook: bearer scheme only, because nothing an application
      // does mid-flight changes what the browser already put in the cookie
      // jar — a cookie 401 is terminal by construction. Bounded, and the
      // replay credential is the hook's return value: re-reading `getToken`
      // here would let a request be re-sent under a session the app has
      // since replaced.
      if (
        response.status === 401 &&
        authMode === "required" &&
        scheme === "bearer" &&
        options.onUnauthorized != null &&
        (internal?.replays ?? 0) < MAX_REPLAYS
      ) {
        let fresh: string | null = null;
        try {
          fresh = await options.onUnauthorized();
        } catch {
          // Renewal failed on the application's side. Surface the server's
          // own 401 — the request's real failure — not the hook's.
          fresh = null;
        }
        if (fresh !== null && fresh !== sentBearer) {
          // The rejected response is discarded by the replay — release its
          // connection before re-sending.
          await releaseBody(response);
          return executeInternal<T>(op, args, {
            replays: (internal?.replays ?? 0) + 1,
            tokenOverride: fresh,
          });
        }
      }
      const text = await response.text();
      let message: string;
      let errorBody: unknown;
      try {
        const json = JSON.parse(text);
        message = json.error ?? json.message ?? text;
        errorBody = json;
      } catch {
        message = text;
      }
      const error = new ApiError(message, response.status, errorBody);
      // Best-effort: an error observer throwing (or rejecting) must not
      // mask the real ApiError on its way out.
      notifyObserver(() => options.onError?.(error));
      throw error;
    }

    // Observers observe, never consume, never break: hand onResponse its
    // own clone so a telemetry body read can't starve the transport's
    // parse below (the clone argument only evaluates when an observer is
    // configured), and let a throwing or rejecting observer fail alone.
    notifyObserver(() => options.onResponse?.(op, response.clone()));

    if (op.response === "raw") return response as unknown as T;
    if (op.response === "void") {
      await releaseBody(response);
      return undefined as T;
    }
    const text = await response.text();
    return (text ? JSON.parse(text) : undefined) as T;
  }

  const transport: Transport = {
    execute: <T>(op: Readonly<OperationSpec>, args?: CallArgs) =>
      executeInternal<T>(op, args),
    urlFor: (op, args) => buildUrl(op, args),
    connect: <TSend, TReceive>(op: Readonly<OperationSpec>, args?: CallArgs) =>
      connectWs<TSend, TReceive>(op, args) as Promise<TypedWebSocket<TSend, TReceive>>,
  };

  async function connectWs<TSend, TReceive>(
    op: Readonly<OperationSpec>,
    args?: CallArgs,
  ): Promise<TypedWebSocket<TSend, TReceive>> {
    // Convert http(s) to ws(s).
    const wsBase = baseUrl.replace(/^http/, (m) => (m === "https" ? "wss" : "ws"));

    let url = `${wsBase}${interpolate(op, args)}`;
    if (args?.query) {
      const params = new URLSearchParams();
      appendQuery(params, args.query);
      const qs = params.toString();
      if (qs) url += `?${qs}`;
    }

    // Ticket handshake first: the long-lived credential rides the header
    // channel; only the single-use proof it returns touches the URL below.
    // The mint reference is transport wiring, declared by the flow.
    const ticketKey = policy.wsTicket ?? null;
    if (op.ws && op.auth === "required" && scheme === "bearer" && ticketKey != null) {
      // Authenticated ticket roundtrip — server must issue a single-use,
      // short-TTL ticket bound to the caller and consume it on upgrade.
      const { ticket } = await executeInternal<{ ticket: string }>(ticketKey, undefined);
      url += `${url.includes("?") ? "&" : "?"}ticket=${encodeURIComponent(ticket)}`;
    }

    // Cookie `required` routes ride same-origin session cookies natively —
    // the WebSocket API has no credentials option, so `"omit"` would
    // silently send the upgrade unauthenticated. Refuse like the fetch
    // path does. `optional` routes allow anonymous upgrades.
    if (scheme === "cookie" && op.auth === "required" && credentials === "omit") {
      throw new Error(
        `Route declared [ws][auth] but options.credentials is "omit"; refusing to send an unauthenticated upgrade (${op.method} ${op.path})`,
      );
    }

    assertSecureTransport(url, {
      allowInsecureHttp: options.allowInsecureHttp === true,
      auth: op.auth !== "none",
      credentials,
    });
    return createTypedWebSocket<TSend, TReceive>(new WebSocket(url));
  }

  return transport;
}

// ---------------------------------------------------------------------------
// Typed WebSocket
// ---------------------------------------------------------------------------

export interface TypedWebSocket<TSend, TReceive> {
  send(event: TSend): void;
  /** Subscribe to socket events; subscribers accumulate — registering
   *  twice fires both (addEventListener-backed, not property assignment). */
  onOpen(handler: () => void): void;
  onMessage(handler: (event: TReceive) => void): void;
  onError(handler: (event: unknown) => void): void;
  onClose(handler: (event: unknown) => void): void;
  /** Close the socket. An application close code and reason ride the
   *  underlying WebSocket's close handshake when given. */
  close(code?: number, reason?: string): void;
  readonly readyState: number;
}

export function createTypedWebSocket<TSend, TReceive>(
  ws: WebSocket,
): TypedWebSocket<TSend, TReceive> {
  return {
    send: (event: TSend) => ws.send(JSON.stringify(event)),
    // addEventListener (not onX property assignment) so multiple
    // subscribers all fire instead of silently replacing each other.
    onOpen: (handler: () => void) => {
      ws.addEventListener("open", () => handler());
    },
    onMessage: (handler: (event: TReceive) => void) => {
      ws.addEventListener("message", (raw) =>
        handler(JSON.parse((raw as MessageEvent).data as string) as TReceive),
      );
    },
    onError: (handler: (event: unknown) => void) => {
      ws.addEventListener("error", (event) => handler(event));
    },
    onClose: (handler: (event: unknown) => void) => {
      ws.addEventListener("close", (event) => handler(event));
    },
    // Forward args only when given: DOM WebSocket's close overloads don't
    // accept explicit `undefined`, and RN's match the same shape.
    close: (code?: number, reason?: string) => {
      if (code === undefined) ws.close();
      else if (reason === undefined) ws.close(code);
      else ws.close(code, reason);
    },
    get readyState() {
      return ws.readyState;
    },
  };
}